#!/usr/bin/env python3
"""Render the x87 matrix from the same JSON returned by the C API and CLI."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_OUTPUT = ROOT / "docs/x87-capabilities.md"


def render(report: dict) -> str:
    if report.get("schema_version") != 1:
        raise ValueError("unsupported x87 capability schema")
    lines = [
        "# x87 capability inventory", "",
        "Generated by `scripts/generate_x87_capabilities.py` from the shared",
        "`neverd x87-capabilities` report. Do not edit the tables by hand.", "",
        "See [semantic contracts](x87-semantics.md) for ownership, qualification",
        "and failure behavior. This inventory is not execution or proof evidence.", "",
        "`implemented` means a route exists under its prerequisites. Numerical",
        "precision and complete architectural state are independent properties.", "",
        "## Source and ABI paths", "",
        "A binary container alone does not specify its long-double ABI. Explicit",
        "state overrides do not supply incoming state or prove call compatibility.", "",
        "| Mode | ABI | State path | Available | Convention default | long double |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for path in report["source_paths"]:
        lines.append("| " + " | ".join(str(path[key]).lower() if isinstance(path[key], bool)
                     else str(path[key]) for key in ("source_mode", "abi", "state_path",
                     "available", "default_path", "long_double")) + " |")
    lines.extend(["", "## Instruction forms", "",
        "Register ranges cover every ST(i) index. Memory ModRM entries are groups;",
        "the report retains full selector construction, short/long environment",
        "widths, WAIT variants, memory directions and flags. Structural validation",
        "continues to reject reserved bits, invalid addressing forms and prefixes.", "",
        "| Instruction | Operand form | Escape | ModRM | Memory bytes | Typed lift | Coverage class |",
        "| --- | --- | --- | --- | --- | --- | --- |"])
    for form in report["forms"]:
        lo, hi = form["first_modrm"], form["last_modrm"]
        modrm = f"{lo:02X}" if lo == hi else f"{lo:02X}–{hi:02X}"
        widths = "/".join(str(n) for n in sorted({v["memory_bytes"] for v in form["variants"]}))
        lines.append(f'| {form["mnemonic"]} | {form["operands"]} | {form["escape"]:02X} | '
                     f'{modrm} | {widths} | {str(form["typed_lift"]).lower()} | {form["coverage_class"]} |')
    lines.extend(["", "Unlisted/reserved and legacy FSTPNCE/FSETPM/FDISI/FENI forms remain",
                  "unsupported by this inventory; recognition elsewhere is not admission.", "",
                  "## Consumer matrix", "",
                  "The following is the x86-64 source/destination slice. The JSON also",
                  "evaluates every i386 and ARM64 destination, native/reference/portable",
                  "backend, and source-state combination. ABI-specific defaults and call",
                  "contracts appear above; explicit path coverage is ABI-independent.", "",
                  "E = supported-exact **numerical scope only**, A = explicitly approximate,",
                  "? = conservative unknown, U = unsupported. Every full-state cell remains",
                  "unknown or unsupported until separately qualified.", "",
                  "| Class | Path | Consumer | Backend | Implemented | Numerical | State |",
                  "| --- | --- | --- | --- | --- | --- | --- |"])
    status = {"supported-exact": "E", "explicitly-approximate": "A",
              "conservative-unknown": "?", "unsupported": "U"}
    for cell in report["coverage"]:
        if cell["source_mode"] != "x86-64" or cell["destination"] != "x86-64":
            continue
        consumer, backend = cell["consumer"], cell["backend"]
        analysis = consumer in ("lift", "ir-analysis", "symbolic", "checked-refinement")
        if analysis and backend != "none":
            continue
        if not analysis and consumer != "concrete" and backend != "native-x86":
            continue
        if consumer == "concrete" and backend == "none":
            continue
        lines.append(f'| {cell["coverage_class"]} | {cell["state_path"]} | {consumer} | {backend} | '
                     f'{str(cell["implemented"]).lower()} | {status[cell["numerical"]]} | '
                     f'{status[cell["architectural_state"]]} |')
    lines.extend(["", "## External state boundaries", "",
                  "These records identify required synchronization, not instruction admission.", "",
                  "| Boundary | Context action | Full-state qualification |",
                  "| --- | --- | --- |"])
    for item in report["state_boundaries"]:
        lines.append(f'| {item["intrinsic"]} | {item["context_action"]} | {item["architectural_state"]} |')
    lines.extend(["", "## Requirements and evidence", "",
                  report["evidence"] + ".", ""])
    for requirements in dict.fromkeys(cell["requirements"] for cell in report["coverage"]):
        if requirements != "none":
            lines.append("- " + requirements + ".")
    lines.extend(["", "Test sources referenced by this inventory:", ""])
    sources = {path for cell in report["coverage"]
               for path in cell["test_sources"].split("; ")} - {"none"}
    for path in sorted(sources):
        lines.append(f"- [{Path(path).name}](../{path})")
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--neverd", required=True, type=Path)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    result = subprocess.run([str(args.neverd.resolve()), "x87-capabilities"],
                            check=True, capture_output=True, text=True)
    content = render(json.loads(result.stdout))
    if args.check:
        if args.output.read_text(encoding="utf-8") != content:
            parser.error("x87 capability documentation is stale; regenerate it with this command without --check")
    else:
        args.output.write_text(content, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
